function sumOfTheDigitsOfHarshadNumber(x) {
  let digitSum = 0;
  let rest = x;

  while (rest > 0) {
    digitSum += rest % 10;
    rest = Math.floor(rest / 10);
  }

  if (x % digitSum === 0) {
    return digitSum;
  }
  return -1;
}

