function sumOfTheDigitsOfHarshadNumber(x) {
  const total = String(x).split('').reduce((acc, d) => acc + Number(d), 0);
  for (let multiple = total; multiple <= x; multiple += total) {
    if (multiple === x) return total;
  }
  return -1;
}
